mkdir -p $TMPDIR/chk && cat > $TMPDIR/chk/check.py <<'EOF'
import csv, sys, os, re
from datetime import date, timedelta
D=sys.argv[1]; P=date(2026,11,27); d=date.fromisoformat
reads={}
def rd(n):
    rows=[r for r in csv.reader(l for l in open(os.path.join(D,n),encoding='utf-8') if not l.startswith('#') and l.strip())]
    h,body=rows[0],rows[1:]; reads[n]=len(body); return [dict(zip(h,r)) for r in body]
def txt(n):
    L=[l for l in open(os.path.join(D,n),encoding='utf-8') if l.strip()]; reads[n]=len(L); return L
con={r['id']:r for r in rd('contracts_register_2026.csv')}
reg={r['id']:r for r in rd('registration_M1M2_2026.csv')}
emp=rd('employee_records_2026.csv'); att=rd('attendance_2026-11.csv'); ab=rd('absences_2026.csv')
ot=rd('overtime_weekly_2026.csv'); pl=rd('payroll_lines_2026-07_to_10.csv'); pr=rd('payroll_runs_2026.csv')
lv={r['id']:r for r in rd('leave_decisions_2026.csv')}; med=rd('medical_exams.csv'); tr=rd('training_proofs_2026.csv')
mel=txt('meldungen_ueberstunden_ordner.txt'); sec=txt('sicherheitserklaerung_2019.md'); txt('ordner-index.md')
F=[];G=[]
def add(rule,ids,extra=''):
    if ids: F.append((rule,sorted(set(ids)),extra))
# M1/M2
late=[i for i,c in con.items() if i not in reg or d(reg[i]['date_filed'])>d(c['start_date'])-timedelta(1)]
add('M1/M2 spaeter als Tag vor erster Schicht',late)
for i,c in con.items():
    if i in reg and (d(c['start_date'])-d(reg[i]['date_filed'])).days<=3 and i not in late: G.append((i,f"M1/M2 {reg[i]['date_filed']}, Beginn {c['start_date']}, rechtzeitig"))
# overtime
o8=[r for r in ot if float(r['overtime_hours'])>8]
add('Ueberstunden ueber 8 h/Woche',[r['id'] for r in o8],f"{len(o8)} Wochen")
for i in sorted({r['id'] for r in ot if 7<=float(r['overtime_hours'])<=8}): G.append((i,'7 bis 8 h Ueberstunden/Woche, nicht ueber 8'))
m26=[l for l in mel if l.startswith('2026') and '(leer)' not in l]
if not m26: add('Ueberstundenwochen ohne Meldung 2026',[r['id'] for r in ot],f"{len(ot)} Wochen")
# payroll lines
months={}
for r in ot: months.setdefault((r['id'],r['week_start'][:7]),0)
nol=[r for r in pl if (r['id'],r['month']) in months and float(r['overtime_line_hours'] or 0)==0]
add('Lohnzeilen ohne Ueberstundenzeile',[r['id'] for r in nol],f"{len(nol)} Lohnzeilen")
# attendance
absd={(a['id'],a['from'],a['to']) for a in ab}
def isabs(i,dt): return any(a==i and d(f)<=d(dt)<=d(t) for a,f,t in absd)
miss=[r for r in att if (not r['start'] or not r['end']) and not isabs(r['id'],r['date'])]
add('Anwesenheitszeilen ohne Beginn/Ende',[r['id'] for r in miss],f"{len(miss)} Zeilen")
for r in att:
    if (not r['start'] or not r['end']) and isabs(r['id'],r['date']): G.append((r['id'],f"{r['date']} ohne Zeiten, Abwesenheit belegt"))
# pay dates
def due(pe):
    x=pe+timedelta(15)
    while x.weekday()>=5: x+=timedelta(1)
    return x
lp=[r for r in pr if d(r['pay_date'])>due(d(r['period_end']))]
add('Lohn spaeter als 15 Tage',[r['period_end'] for r in lp],f"{len(lp)} Perioden")
for r in pr:
    if r not in lp and (d(r['period_end'])+timedelta(15)).weekday()>=5 and d(r['pay_date'])>d(r['period_end'])+timedelta(15): G.append((r['period_end'],f"Frist auf {due(d(r['period_end']))} verschoben, gezahlt {r['pay_date']}"))
# leave
def m6(s): return date(s.year+(s.month+5)//12,(s.month+5)%12+1,s.day)
owed=[i for i,c in con.items() if m6(d(c['start_date']))<=P]
add('Urlaubsbescheid fehlt',[i for i in owed if i not in lv])
add('Urlaubsbescheid unter 20 Tagen',[i for i in owed if i in lv and int(lv[i]['days'])<20])
for i in owed:
    if i in lv and int(lv[i]['days'])==20: G.append((i,'20 Tage, gleich Grenze'))
for i,c in con.items():
    if i not in owed and m6(d(c['start_date']))<=P+timedelta(14): G.append((i,f"6 Monate erst am {m6(d(c['start_date']))}, noch nicht geschuldet"))
# records
emp_ids=[r['id'] for r in emp]; empty=sum(1 for r in emp for k,v in r.items() if k!='id' and not v.strip())
add('Leere Felder in Akten',[r['id'] for r in emp if any(not v.strip() for v in r.values())],f"{empty} Felder")
add('Akte fehlt',[i for i in con if i not in emp_ids])
# medical
lim=date(P.year-2,P.month,P.day)
old=[r['id'] for r in med if d(r['last_exam_date'])<lim]; add('Untersuchung aelter als 24 Monate',old+[i for i in con if i not in {r['id'] for r in med}])
for r in med:
    if lim<=d(r['last_exam_date'])<=lim+timedelta(10): G.append((r['id'],f"{r['last_exam_date']}, knapp unter 24 Monaten"))
# security
listed={l[2:].strip() for l in sec if l.startswith('- ')}
add('Stellenbezeichnung fehlt in Sicherheitserklaerung',[t for t in {c['role'] for c in con.values()} if t not in listed])
# training
new=[i for i,c in con.items() if P-timedelta(365)<=d(c['start_date'])<=P]; trd={r['id']:r for r in tr}
add('Unterweisung spaeter als Einstellung/fehlt',[i for i in new if i not in trd or d(trd[i]['training_date'])>d(con[i]['start_date'])])
for i in new:
    if i in trd and trd[i]['training_date']==con[i]['start_date']: G.append((i,'Unterweisung am Einstellungstag'))
print('READ',reads)
for f in F: print('FUND',f)
for g in G: print('GRENZ',g)
print('SUM',sum(reads.values()),len(F),len(G))
EOF
